// Golden parity with ref/pixiv-dl (ENG-003): the vectors are generated by scripts/gen-golden.py,
// which runs the script's own safe_component.

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { sanitizeToken } from '../../src/shared/pattern';

interface TextVector {
  in: string;
  out: string;
}

const vectors = JSON.parse(
  readFileSync(new URL('../golden/safe_component.json', import.meta.url), 'utf8'),
) as TextVector[];

describe('golden: safe_component (ref/pixiv-dl)', () => {
  it('golden: safe_component.json has at least 200 vectors', () => {
    expect(vectors.length).toBeGreaterThanOrEqual(200);
  });

  it.each(vectors.map((v, i) => [i, v] as const))(
    'sanitizeToken(parityOnly): vector %i equals safe_component',
    (_index, v) => {
      expect(sanitizeToken(v.in, { parityOnly: true })).toBe(v.out);
    },
  );
});
